/// Non-secret environment variables injected into every subprocess Lucidos spawns, effective on the next one with no restart. They appear in logs and events, so use request_credential for an API key, token or password.
#[derive(clap::Subcommand)]
pub enum EnvVarsCmd {
    /// Every variable with its value.
    List,
    /// Create or replace one.
    Set {
        /// Uppercase letters, digits and underscores, not starting with a digit. An engine-owned name (CRED_*, OAUTH_*, PG*, PATH, LUCIDOS_*) is rejected.
        #[arg(long)]
        name: String,
        /// Plaintext, non-secret. Use a credential for a secret.
        #[arg(long)]
        value: String,
    },
    /// Remove one by name.
    Delete {
        /// Name of the variable to delete.
        #[arg(long)]
        name: String,
    },
}

/// Execute a `lucidos env-vars <op>` command against the parent workspace.
pub fn dispatch_env_vars(ws: &Workspace, cmd: EnvVarsCmd) -> Result<(), BoxError> {
    match cmd {
        EnvVarsCmd::List => {
            let url = format!("{}/api/v1/env-vars", ws.base_url());
            let req = client()?.get(&url);
            send_and_print("GET", &url, req)
        }
        EnvVarsCmd::Set { name, value } => {
            let url = format!("{}/api/v1/env-vars", ws.base_url());
            let mut body = serde_json::Map::new();
            body.insert("name".into(), serde_json::json!(name));
            body.insert("value".into(), serde_json::json!(value));
            let req = client()?.post(&url).json(&serde_json::Value::Object(body));
            send_and_print("POST", &url, req)
        }
        EnvVarsCmd::Delete { name } => {
            let url = format!("{}/api/v1/env-vars", ws.base_url());
            let mut query: Vec<(&str, String)> = Vec::new();
            query.push(("name", name.to_string()));
            let req = client()?
                .delete(&url)
                .query(&query)
                .json(&serde_json::json!({}));
            send_and_print("DELETE", &url, req)
        }
    }
}

/// The chat-model registry behind the Lucidos Agent's model picker. A builtin can be disabled but not removed. Switch the ACTIVE model with set_preference(key='chat_model').
#[derive(clap::Subcommand)]
pub enum ModelsCmd {
    /// Every model, enabled and disabled, builtin and user.
    List,
    /// Register a new model in the picker.
    Add {
        /// The string sent in API requests (e.g. 'z-ai/glm-5.2').
        #[arg(long)]
        id: String,
        /// Display name; defaults to the id.
        #[arg(long)]
        label: Option<String>,
        /// Backend that serves the model.
        #[arg(long)]
        provider: String,
        /// Lower sorts first; user models default to 1000.
        #[arg(long)]
        sort_order: Option<i64>,
        /// Context window in tokens (e.g. 1048576), what the model actually serves. Omitting it guesses from the model id: 1M for an id carrying [1m], 400k for gpt-5*, 200k for everything else including OpenRouter, Gemini and local ids however large they are. The guess errs low on purpose.
        #[arg(long)]
        context_window: Option<i64>,
    },
    /// Edit label, provider, sort_order or enabled.
    Update {
        /// Model id (the request string, e.g. 'z-ai/glm-5.2').
        #[arg(long)]
        id: String,
        /// Display name; defaults to the id.
        #[arg(long)]
        label: Option<String>,
        /// Backend that serves the model.
        #[arg(long)]
        provider: Option<String>,
        /// Lower sorts first; user models default to 1000.
        #[arg(long)]
        sort_order: Option<i64>,
        /// Whether the model is enabled (shown in the picker).
        #[arg(long)]
        enabled: Option<bool>,
        /// Context window in tokens (e.g. 1048576), what the model actually serves. Omitting it guesses from the model id: 1M for an id carrying [1m], 400k for gpt-5*, 200k for everything else including OpenRouter, Gemini and local ids however large they are. The guess errs low on purpose.
        #[arg(long)]
        context_window: Option<i64>,
    },
    /// Delete a user-added model.
    Delete {
        /// Model id (the request string, e.g. 'z-ai/glm-5.2').
        #[arg(long)]
        id: String,
    },
}

/// Execute a `lucidos models <op>` command against the parent workspace.
pub fn dispatch_models(ws: &Workspace, cmd: ModelsCmd) -> Result<(), BoxError> {
    match cmd {
        ModelsCmd::List => {
            let url = format!("{}/api/v1/models", ws.base_url());
            let req = client()?.get(&url);
            send_and_print("GET", &url, req)
        }
        ModelsCmd::Add {
            id,
            label,
            provider,
            sort_order,
            context_window,
        } => {
            let url = format!("{}/api/v1/models", ws.base_url());
            let mut body = serde_json::Map::new();
            body.insert("id".into(), serde_json::json!(id));
            if let Some(v) = label {
                body.insert("label".into(), serde_json::json!(v));
            }
            body.insert("provider".into(), serde_json::json!(provider));
            if let Some(v) = sort_order {
                body.insert("sort_order".into(), serde_json::json!(v));
            }
            if let Some(v) = context_window {
                body.insert("context_window".into(), serde_json::json!(v));
            }
            let req = client()?.post(&url).json(&serde_json::Value::Object(body));
            send_and_print("POST", &url, req)
        }
        ModelsCmd::Update {
            id,
            label,
            provider,
            sort_order,
            enabled,
            context_window,
        } => {
            let url = format!("{}/api/v1/models", ws.base_url());
            let mut query: Vec<(&str, String)> = Vec::new();
            query.push(("id", id.to_string()));
            let mut body = serde_json::Map::new();
            if let Some(v) = label {
                body.insert("label".into(), serde_json::json!(v));
            }
            if let Some(v) = provider {
                body.insert("provider".into(), serde_json::json!(v));
            }
            if let Some(v) = sort_order {
                body.insert("sort_order".into(), serde_json::json!(v));
            }
            if let Some(v) = enabled {
                body.insert("enabled".into(), serde_json::json!(v));
            }
            if let Some(v) = context_window {
                body.insert("context_window".into(), serde_json::json!(v));
            }
            let req = client()?
                .put(&url)
                .query(&query)
                .json(&serde_json::Value::Object(body));
            send_and_print("PUT", &url, req)
        }
        ModelsCmd::Delete { id } => {
            let url = format!("{}/api/v1/models", ws.base_url());
            let mut query: Vec<(&str, String)> = Vec::new();
            query.push(("id", id.to_string()));
            let req = client()?
                .delete(&url)
                .query(&query)
                .json(&serde_json::json!({}));
            send_and_print("DELETE", &url, req)
        }
    }
}
